// Regenerate the file:// fallback after editing any JSON configuration.
// Run from the project root: node scripts/build-data.cjs
const fs = require('node:fs');
const path = require('node:path');

const dataDirectory = path.join(__dirname, '..', 'data');
const readJson = (name) => JSON.parse(fs.readFileSync(path.join(dataDirectory, name), 'utf8'));

const data = {
	positions: readJson('positions.json'),
	teams: readJson('teams.json'),
	names: readJson('player-names.json'),
	statDefaults: readJson('stat-defaults.json'),
};

const output = [
	'// Generated by scripts/build-data.cjs. Edit the JSON files, then regenerate.',
	`window.DIAMOND_LOCAL_DATA = ${JSON.stringify(data, null, '\t')};`,
	'',
].join('\n');

fs.writeFileSync(path.join(dataDirectory, 'local-data.js'), output);
console.log('Updated data/local-data.js from JSON configuration.');
